/*
 * Pro tips
 * - Count first, then sort DISTINCT characters by descending frequency.
 * - Break ties by ascending character code; HashMap iteration order cannot provide this guarantee.
 * - Append each character its full count of times after sorting the distinct keys.
 * - Check equal frequencies, mixed case, and all-identical input.
 * - Complexity: O(n + u log u) time and O(n+u) space including output.
 */

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

class Solution {
    public static String sortByFrequency(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        List<Character> chars = new ArrayList<>(freq.keySet());
        Collections.sort(chars, (a, b) -> {
            int freqCompare = freq.get(b).compareTo(freq.get(a));
            if (freqCompare != 0) {
                return freqCompare;
            }
            return a.compareTo(b);
        });

        StringBuilder result = new StringBuilder();
        for (char c : chars) {
            int count = freq.get(c);
            for (int i = 0; i < count; i++) {
                result.append(c);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
        String res = sortByFrequency(s);
        System.out.println(res);
    }
}
